import {openDB,read,save} from './db.js';
import {openPhotos,photoOf,savePhoto,removePhoto,shrinkPhoto} from './photos.js';
import {RECEIPT_PAPERS,DEFAULT_PAPER,receiptLines,receiptRows,escPos} from './receipt.js';
import {printerSettings,savePrinterSettings,bluetoothAvailable,printerName,connectPrinter,forgetPrinter,sendToPrinter} from './printer.js';
import {online,cloudUser,setCloudUser,cloudToken,cloudAccept,cloudForget,pendingCommand,clearPending,cloudCall,cloudCommand} from './cloud.js';
const $=s=>document.querySelector(s),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={more:'M4 12a1.6 1.6 0 1 0 3.2 0a1.6 1.6 0 1 0-3.2 0M10.4 12a1.6 1.6 0 1 0 3.2 0a1.6 1.6 0 1 0-3.2 0M16.8 12a1.6 1.6 0 1 0 3.2 0a1.6 1.6 0 1 0-3.2 0',bolt:'M13 2 4 14h7l-1 8 9-12h-7z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',cart:'M3 3h2l3 13h11l2-9H6M9 20h.01M18 20h.01',box:'m3 7 9-4 9 4v10l-9 4-9-4ZM3 7l9 4 9-4M12 11v10M7 5l10 4',truck:'M3 5h11v12H3zM14 9h4l3 4v4h-7M7 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4M17 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M18 3a4 4 0 0 1 0 7M22 21v-3a4 4 0 0 0-3-4',wallet:'M20 8V5H4a2 2 0 0 0 0 4h17v11H4a2 2 0 0 1-2-2V7M21 12h-6v5h6M17 14.5h.01',chart:'M4 3v18h17M8 15l4-5 4 2 5-8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',down:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16',check:'m5 12 4 4L19 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',grain:'M12 22V3M12 9C6 9 5 5 5 2c5 0 7 3 7 7ZM12 16c-6 0-7-4-7-7 5 0 7 3 7 7ZM12 12c6 0 7-4 7-7-5 0-7 3-7 7ZM12 19c6 0 7-4 7-7-5 0-7 3-7 7Z',close:'M6 6l12 12M18 6 6 18',menu:'M3 6h18M3 12h18M3 18h18',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',store:'M3 10V5h18v5M5 10v11h14V10M8 21v-7h8v7M2 10c0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0',receipt:'M5 3h14v19l-3-2-4 2-4-2-3 2ZM8 7h8M8 11h8M8 15h4',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6ZM8 12l3 3 5-6',minus:'M5 12h14',trash:'M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3',cash:'M3 6h18v12H3zM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6M6.5 9.5h.01M17.5 14.5h.01',phone:'M7 2h10v20H7zM11 18h2',bank:'M3 10l9-6 9 6M5 10v8M9.5 10v8M14.5 10v8M19 10v8M3 21h18',book:'M5 3h12a2 2 0 0 1 2 2v16H7a2 2 0 0 1-2-2ZM5 17a2 2 0 0 1 2-2h12M9 7h6',split:'M12 3v18M4 8h5M4 13h5M15 11h5M15 16h5',camera:'M4 7h4l2-3h4l2 3h4v13H4zM12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',backspace:'M9 5h11v14H9l-6-7ZM12 9l5 6M17 9l-5 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.box}"/></svg>`;
const button=(label,action,kind='',ico='',attrs='')=>`<button class="btn ${kind}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const field=(label,name,type='text',value='',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;
const select=(label,name,options,value='')=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${e(v)}" ${v===value?'selected':''}>${e(l)}</option>`;}).join('')}</select></div>`;
const num=(label,name,value='0',step='.01',extra='')=>field(label,name,'number',value,`min="0" step="${step}" required ${extra}`);
const check=(label,name)=>`<div class="field"><label class="checkbox"><input type="checkbox" name="${name}">${label}</label></div>`;
const time=at=>new Date(at).toLocaleTimeString('en-PH',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'});
const date=at=>new Date(at).toLocaleDateString('en-PH',{timeZone:'Asia/Manila',month:'short',day:'numeric'});
const table=(headers,rows,empty='No records yet.')=>`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty">${empty}</div></td></tr>`}</tbody></table></div>`;
const row=cells=>`<tr>${cells.map(x=>`<td>${x}</td>`).join('')}</tr>`;
// The app opens on selling: that's what a cashier does all day.
const START_PAGE='pos',ALL_PRODUCTS='All products';
let db,photos,state,page=START_PAGE,cart=[],cartId=uid(),category=ALL_PRODUCTS,search='',held=null,busy=false,reportFrom=day(),reportTo=day();
// The menu, cashier screens first. Short words, because the menu is a slim icon rail.
// phoneBar: shown in the phone's bottom bar; the others open from "More · Iba pa".
const nav=[{page:'pos',icon:'cart',label:'Sell',tl:'Benta',phoneBar:true},{page:'customers',icon:'users',label:'Utang',tl:'Listahan',phoneBar:true},{page:'cash',icon:'wallet',label:'Cash',tl:'Kaha',phoneBar:true},{page:'inventory',icon:'box',label:'Stocks',tl:'Paninda',phoneBar:true},{page:'dashboard',icon:'grid',label:'Today',tl:'Ngayon'},{page:'purchases',icon:'truck',label:'Restock',tl:'Bili'},{page:'reports',icon:'chart',label:'Reports',tl:'Ulat'},{page:'settings',icon:'settings',label:'Settings',tl:'Ayos'}];
const CASHIER_PAGES=['pos','customers','cash'];   // the only screens an online cashier account opens
const menuPages=()=>online&&cloudUser?.role==='cashier'?nav.filter(x=>CASHIER_PAGES.includes(x.page)):nav;
// Sell screen settings.
const KILO_QUICK=[500,1000,2000,3000,5000,10000];   // grams offered as one-tap weights
const SACK_QUICK=[1,2,3,5];                        // sacks offered as one-tap amounts
const PAD_MAX_DECIMALS=3,PAD_MAX_LENGTH=7;          // keypad accepts up to 9999.999
const CASH_ROUND_UPS=[10000,50000,100000];         // centavos: suggest the next ₱100, ₱500 and ₱1,000
const TILE_TONES=4;                                // colors for products without a photo
const PAY_METHODS=[{value:'Cash',icon:'cash',label:'Cash',hint:'Pera'},{value:'GCash',icon:'phone',label:'GCash',hint:'E-wallet'},{value:'Maya',icon:'phone',label:'Maya',hint:'E-wallet'},{value:'Bank Transfer',icon:'bank',label:'Bank',hint:'Transfer'},{value:'Utang',icon:'book',label:'Utang',hint:'Listahan'},{value:'Split payment',icon:'split',label:'Split',hint:'Cash + e-wallet'}];
const DIGITAL_METHODS=['GCash','Maya','Bank Transfer'];
const TENDER_FIELDS=['received','cash','digital'];   // amount boxes the cashier types on the payment panel
const count=n=>new Intl.NumberFormat('en-PH',{maximumFractionDigits:PAD_MAX_DECIMALS}).format(n);
// While a pop-up is open the message moves inside it; otherwise the pop-up would cover it.
function toast(message){($('#modal').open?$('#modal'):document.body).append($('#toast'));$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function commit(type,data,id){if(online){const result=await cloudCommand(type,data,id,state.revision);state=result.state;setCloudUser(result.user);if(result.conflict)throw Error('Another device updated this store. The latest records are loaded; review the amount and retry.');return;}const next=transact(state,type,data,{id});await save(db,next,state.revision);state=next;}
const lowProducts=()=>state.products.filter(p=>p.stock<=p.minimum);
function head(title,sub,actions='',eye='YOUR STORE, IN VIEW'){return `<div class="page-head"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function navButton({page:id,icon:ico,label,tl,phoneBar}){const low=id==='inventory'&&lowProducts().length;return `<button data-page="${id}" class="${page===id?'active':''} ${phoneBar?'on-bar':''}" ${page===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span><small lang="tl">${tl}</small>${low?`<span class="badge" aria-label="${low} low on stock">${low}</span>`:''}</button>`;}
// Phones only: one button for the screens that do not fit the bottom bar. It lights up while one of them is open.
function moreButton(){const extra=menuPages().filter(x=>!x.phoneBar);return extra.length?`<button class="nav-more ${extra.some(x=>x.page===page)?'active':''}" data-action="more">${icon('more')}<span>More</span><small lang="tl">Iba pa</small></button>`:'';}
function renderBase(){const title=nav.find(x=>x.page===page)?.label||'Sales';$('#app').innerHTML=`<div class="shell"><aside class="sidebar rail"><div class="brand"><img src="icon.svg" alt="StorePOS"></div><nav class="nav" aria-label="Main navigation">${menuPages().map(navButton).join('')}${moreButton()}</nav><div class="owner" title="${e(state.store.owner)}"><span class="avatar">${e((state.store.owner||'Owner').slice(0,2).toUpperCase())}</span></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><strong class="store-name">${e(state.store.name)}</strong><span>/</span><span class="page-name">${title}</span></div><div class="top-actions"><span class="saved"><span class="dot"></span> Saved on this device</span><span class="top-date">${new Date().toLocaleDateString('en-PH',{timeZone:'Asia/Manila',month:'short',day:'numeric',year:'numeric'})}</span></div></header><div class="workspace ${page==='pos'?'pos-page':''}">${({dashboard,inventory,purchases,customers,cash,reports,settings,pos,history}[page]||dashboard)()}<footer class="footnote"><span>${state.demo?'Sample data · ':''}StorePOS Lite &nbsp; / &nbsp; Made for your everyday business</span><span>${currentSession(state)?'● Cash session open':'○ Cash session closed'} &nbsp; · &nbsp; Internal records only</span></footer></div></main></div>`;bind();}
function saleDebt(sale){return state.ledger.filter(x=>x.saleId===sale.id).reduce((a,x)=>a+x.amount,0);}
function overdue(id){return state.sales.some(s=>s.customerId===id&&saleDebt(s)>0&&s.dueDate<day());}
function salesTable(sales,compact=false){return table(compact?['Transaction','Customer','Amount','Status']:['Transaction','Customer','Amount','Payment','Status',''],sales.map(s=>{const debt=saleDebt(s),status=s.refunded?'Refunded':debt===s.total&&debt?'Unpaid':debt?'Partially paid':'Paid',customer=state.customers.find(c=>c.id===s.customerId);const cells=[`<button class="text-link" data-action="receipt" data-id="${s.id}">${e(s.ref)}</button><small>${date(s.at)} · ${time(s.at)}</small>`,e(customer?.name||'Walk-in customer'),`<strong>${money(s.total)}</strong>`];if(!compact)cells.push([...new Set(state.payments.filter(p=>p.saleId===s.id&&p.kind==='Sale').map(p=>p.method))].join(' + ')||'Utang');cells.push(`<span class="pill ${debt?'warn':s.refunded?'red':''}">${status}</span>`);if(!compact)cells.push(s.refunded?'—':button('Refund','refund','secondary small','','data-id="'+s.id+'"'));return row(cells);}));}
// ---------- Easy screens: big numbers and big tiles ----------
// A screen title in English with the Tagalog word beside it.
function pageTitle(label,tl,actions=''){return `<div class="easy-head"><h1>${label} <small lang="tl">· ${tl}</small></h1>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
// One number that can be read from across the counter. tone: good · warn · ''
function bigNumber(label,tl,value,note='',tone=''){return `<div class="big-number ${tone}"><span>${label}${tl?` <small lang="tl">· ${tl}</small>`:''}</span><strong>${value}</strong>${note?`<small>${note}</small>`:''}</div>`;}
// A big square button. go = where it leads: doAction(…) or goTo(…). tone: good · warn · active · ''
function tile(label,tl,go,ico,tone='',note=''){return `<button class="tile ${tone}" ${go}>${icon(ico)}<strong>${label}</strong>${tl?`<small lang="tl">${tl}</small>`:''}${note?`<span class="tile-note">${note}</span>`:''}</button>`;}
const doAction=(name,id='')=>`data-action="${name}"${id?` data-id="${e(id)}"`:''}`,goTo=id=>`data-page="${id}"`;
// Radio buttons drawn as tiles (how they paid, where the money came from). options: {value, icon, label, hint}
function choiceTiles(name,options,checked,label){return `<div class="pay-methods" role="radiogroup" aria-label="${label}">${options.map(o=>`<label class="pay-tile"><input type="radio" name="${name}" value="${e(o.value)}" ${o.value===checked?'checked':''}>${icon(o.icon)}<strong>${o.label}</strong><small>${o.hint}</small></label>`).join('')}</div>`;}
const initials=name=>e(name.split(' ').map(n=>n[0]).slice(0,2).join('').toUpperCase());
const plural=(n,one,many=one+'s')=>`${n} ${n===1?one:many}`;
const bill=centavos=>'₱'+new Intl.NumberFormat('en-PH').format(centavos/100);   // "₱1,000" for counting money
const rows=list=>`<div class="list-rows">${list.map(([label,value])=>`<div class="row"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`;

// ---------- Today · Ngayon: three big numbers and two reminders ----------
function dashboard(){const m=metrics(state),low=lowProducts(),session=currentSession(state),owing=state.customers.filter(c=>balance(state,c.id)>0),late=owing.filter(c=>overdue(c.id)).length;
 return pageTitle('Today','Ngayon',button('Sales today','history','secondary','receipt'))+`<p class="greeting">Magandang araw, ${e(state.store.owner)}! Here is ${e(state.store.name)} on ${date(new Date())}.</p><section class="big-numbers">${bigNumber('Sold today','Benta',money(m.revenue),plural(m.sales.length,'sale'),'good')}${bigNumber('Money in the cash box','Pera sa kaha',session?money(expectedCash(state)):'Closed',session?`Open since ${time(session.openedAt)}`:'Open it before selling',session?'':'warn')}${bigNumber('Customers owe you','Utang',money(m.credit),owing.length?plural(owing.length,'person','people')+(late?` · ${late} late`:''):'Nobody owes you',late?'warn':'')}</section><section class="tile-grid two">${low.length?tile(`${plural(low.length,'rice','rice')} running low`,'Paubos na',goTo('inventory'),'box','warn',low.slice(0,3).map(p=>e(p.name)).join(', ')):tile('Stocks are fine','Sapat ang paninda',goTo('inventory'),'box','good')}${session?tile('Cash box is open','Bukas ang kaha',goTo('cash'),'wallet','good'):tile('Open the cash box','Buksan ang kaha',doAction('open'),'wallet','warn')}</section>`;}

// ---------- Stocks · Paninda: the same rice tiles as Sell, showing kilos left ----------
function stockTile(p){const out=!p.stock,low=!out&&p.stock<=p.minimum;return `<button class="product-tile stock-tile" ${doAction('stock-open',p.id)}>${productThumb(p,'tile-thumb')}<strong class="tile-name">${e(p.name)}</strong><span class="tile-price">${qty(p.stock)}<small> kg left</small></span><span class="tile-stock ${out||low?'warn':''}">${out?'Out of stock · Ubos na':low?'Running low · Paubos na':`${money(p.price)} / kg`}</span></button>`;}
function inventory(){const filtered=state.products.filter(p=>(p.name+' '+p.sku).toLowerCase().includes(search.toLowerCase())),kilos=state.products.reduce((a,p)=>a+p.stock,0),worth=state.products.reduce((a,p)=>a+p.stockValue,0);
 return pageTitle('Stocks','Paninda',button('Export','export-stock','secondary','down'))+`<section class="tile-grid three">${tile('Restock','Bili ng paninda',doAction('purchase'),'truck','good')}${tile('Add rice','Bagong bigas',doAction('product'),'plus')}${tile('Stock history','Kasaysayan',doAction('movements'),'clock')}</section><div class="shelf-top"><div class="search">${icon('search')}<input id="search" placeholder="Search rice · Hanapin" aria-label="Search products" value="${e(search)}"></div></div><p class="period-line">${plural(state.products.length,'rice','rice')} · ${qty(kilos)} kg in stock · worth ${money(worth)} at cost. Tap a rice to count it, restock it or add a photo.</p><div class="product-grid">${filtered.map(stockTile).join('')||(state.products.length?'<div class="empty">No rice matches your search.</div>':'<div class="empty"><strong>No rice yet.</strong><br>Tap <b>Add rice</b> to start.</div>')}</div>`;}

// ---------- Restock · Bili: orders waiting for delivery first ----------
const MONEY_SOURCES=[{value:'External',icon:'bank',label:'Paid outside',hint:'Hindi galing sa kaha'},{value:'Register',icon:'wallet',label:'From the cash box',hint:'Galing sa kaha'}];
const RECEIVE_SOURCES=[...MONEY_SOURCES,{value:'Unpaid',icon:'book',label:'Not paid yet',hint:'Utang sa supplier'}];
const sourceName=value=>RECEIVE_SOURCES.find(x=>x.value===value)?.label||value;
function purchases(){const waiting=state.purchases.filter(p=>!p.receivedAt).reverse(),received=state.purchases.filter(p=>p.receivedAt).reverse();
 return pageTitle('Restock','Bili')+`<section class="tile-grid two">${tile('New order','Bagong order',doAction('purchase'),'plus','good')}${tile('See stocks','Paninda',goTo('inventory'),'box')}</section><h2 class="section-label">Waiting for delivery <small lang="tl">· Hinihintay</small></h2>${waiting.length?`<section class="cards">${waiting.map(p=>`<div class="card"><div class="card-text"><strong>${e(p.productName)}</strong><small>${p.sacks} sacks × ${qty(p.sackGrams)} kg = ${qty(p.quantity)} kg · ${e(p.supplier)} · ${date(p.at)}</small></div><strong class="card-amount">${money(p.total)}</strong>${button('Receive · Tanggapin','receive','','check',`data-id="${p.id}"`)}</div>`).join('')}</section>`:'<div class="empty">Nothing is waiting. Tap <b>New order</b> when you buy from your supplier.</div>'}<h2 class="section-label">Received <small lang="tl">· Natanggap na</small></h2><section class="panel">${table(['Supplier / Date','Rice','Sacks','Total','Paid from'],received.map(p=>row([`<strong>${e(p.supplier)}</strong><small>${date(p.receivedAt)} · ${e(p.reference||'No reference')}</small>`,e(p.productName),`${p.sacks} × ${qty(p.sackGrams)} kg`,money(p.total),p.source==='Unpaid'?`<span class="pill warn">${sourceName(p.source)}</span>`:sourceName(p.source)])),'No deliveries yet.')}</section><p class="subtitle spacer">Stock goes up only when you receive an order. The new cost is mixed with the old cost (weighted average).</p>`;}

// ---------- Utang · Listahan: who owes, late ones first ----------
const owedOrder=(a,b)=>overdue(b.id)-overdue(a.id)||balance(state,b.id)-balance(state,a.id)||a.name.localeCompare(b.name);
const nextDue=id=>state.sales.filter(s=>s.customerId===id&&saleDebt(s)>0).map(s=>s.dueDate).sort()[0];
function personRow(c,go='customer-open'){const owe=balance(state,c.id),late=overdue(c.id),due=nextDue(c.id);return `<button class="person ${late?'late':''}" ${doAction(go,c.id)}><span class="avatar">${initials(c.name)}</span><span class="person-name"><strong>${e(c.name)}</strong><small>${late?'Late · Lampas na':owe?(due?`Pay by ${date(due)}`:'Has utang'):'All paid · Bayad na'}</small></span><strong class="person-owe">${money(owe)}</strong></button>`;}
function customers(){const owing=state.customers.filter(c=>balance(state,c.id)>0),late=owing.filter(c=>overdue(c.id)).length,collected=state.payments.filter(x=>x.kind==='Collection'&&day(x.at)===day()).reduce((a,x)=>a+x.amount,0),list=state.customers.filter(c=>c.name.toLowerCase().includes(search.toLowerCase())).sort(owedOrder);
 return pageTitle('Utang','Listahan')+`<section class="big-numbers one">${bigNumber('Customers owe you','Kabuuang utang',money(metrics(state).credit),`${plural(owing.length,'person','people')}${late?` · ${late} late`:''} · collected today ${money(collected)}`,late?'warn':'')}</section><section class="tile-grid two">${tile('Collect payment','Singilin',doAction('collect-pick'),'cash','good')}${tile('New customer','Bagong suki',doAction('customer'),'plus')}</section><div class="shelf-top"><div class="search">${icon('search')}<input id="search" placeholder="Find a name · Hanapin" aria-label="Find a customer" value="${e(search)}"></div></div><section class="people">${list.map(c=>personRow(c)).join('')||`<div class="empty">${state.customers.length?'No name matches your search.':'No customers yet. Tap <b>New customer</b>.'}</div>`}</section>`;}

// ---------- Cash · Kaha: what should be in the box, and four big jobs ----------
function cash(){const session=currentSession(state),m=metrics(state),digital=state.payments.filter(x=>day(x.at)===day()&&x.method!=='Cash').reduce((a,x)=>a+x.amount,0),last=[...state.sessions].reverse().find(x=>x.closedAt);
 const top=session?`<section class="big-numbers one">${bigNumber('Should be in the cash box','Dapat nasa kaha',money(expectedCash(state)),`Open since ${time(session.openedAt)} · started with ${money(session.opening)}`,'good')}</section><section class="tile-grid">${tile('Count and close','Bilangin at isara',doAction('close'),'check','good')}${tile('Expense','Gastos',doAction('expense'),'receipt')}${tile('Put money in','Dagdag pera',doAction('cash-move','in'),'plus')}${tile('Take money out','Kuha pera',doAction('cash-move','out'),'minus')}</section>`
  :`<section class="big-numbers one">${bigNumber('The cash box is closed','Sarado ang kaha',last?money(last.actual):'—',last?`Last closed ${date(last.closedAt)} · ${time(last.closedAt)}${last.variance?` · ${last.variance<0?'short':'over'} ${money(Math.abs(last.variance))}`:' · correct'}`:'Open it before the first sale','warn')}</section><section class="tile-grid two">${tile('Open the cash box','Buksan ang kaha',doAction('open'),'wallet','good')}${tile('Expense','Gastos',doAction('expense'),'receipt')}</section>`;
 return pageTitle('Cash','Kaha')+top+`<p class="period-line">Today: expenses ${money(m.expenses)} · GCash, Maya and bank ${money(digital)} (not in the box).</p><h2 class="section-label">History <small lang="tl">· Kasaysayan</small></h2><div class="two-col"><section class="panel"><div class="panel-head"><h2>Money in and out</h2></div>${table(['Reason','Date','Amount'],[...state.cashMoves].reverse().slice(0,10).map(x=>row([e(x.reason),date(x.at),money(x.amount)])))}</section><section class="panel"><div class="panel-head"><h2>Expenses</h2></div>${table(['What','Paid from','Amount'],[...state.expenses].reverse().slice(0,10).map(x=>row([`<strong>${e(x.description)}</strong><small>${e(x.category)} · ${date(x.at)}</small>`,sourceName(x.source),money(x.amount)])))}</section></div><section class="panel spacer"><div class="panel-head"><h2>Closings</h2></div>${table(['Opened','Closed','Should be','Counted','Difference','Note'],[...state.sessions].filter(x=>x.closedAt).reverse().map(x=>row([date(x.openedAt),date(x.closedAt)+' · '+time(x.closedAt),money(x.expected),money(x.actual),`<span class="pill ${x.variance?'warn':''}">${money(x.variance)}</span>`,e(x.reason||'Correct')])) )}</section>`;}

// ---------- Reports · Ulat: pick a period, read three numbers, details below ----------
const REPORT_PERIODS=[{id:'today',label:'Today',tl:'Ngayon'},{id:'week',label:'Last 7 days',tl:'7 araw'},{id:'month',label:'This month',tl:'Ngayong buwan'}];
const WEEK_DAYS=7;
function periodRange(id){const today=day();if(id==='today')return [today,today];if(id==='week'){const d=new Date();d.setUTCDate(d.getUTCDate()-(WEEK_DAYS-1));return [day(d),today];}return [today.slice(0,8)+'01',today];}
// Sales of the last 7 days as a line.
function weekChart(){const week=[];for(let i=WEEK_DAYS-1;i>=0;i--){const d=new Date();d.setUTCDate(d.getUTCDate()-i);week.push({label:d.toLocaleDateString('en-PH',{timeZone:'Asia/Manila',weekday:'short'}),value:metrics(state,day(d)).revenue});}const total=week.reduce((a,x)=>a+x.value,0),max=Math.max(...week.map(x=>x.value),10000);const points=week.map((x,i)=>`${45+i*77},${150-x.value/max*110}`).join(' ');
 return `<section class="panel"><div class="panel-head"><div><h2>Last 7 days <small lang="tl">· 7 araw</small></h2><p>${money(total)} sold</p></div></div><div class="panel-body"><svg class="chart" viewBox="0 0 540 190" role="img" aria-label="Sales over the last seven days: ${week.map(x=>`${x.label} ${money(x.value)}`).join(', ')}"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#dce9cd" stop-opacity=".6"/><stop offset="1" stop-color="#f9fbf6" stop-opacity=".2"/></linearGradient></defs>${[0,1,2,3].map(i=>`<path class="grid" d="M42 ${40+i*37}H520"/><text x="0" y="${44+i*37}">${(max/100*(1-i/3)/1000).toFixed(1)}k</text>`).join('')}<polygon points="45,151 ${points} 507,151" fill="url(#fill)"/><polyline points="${points}" fill="none" stroke="#719251" stroke-width="2.5" stroke-linejoin="round"/>${week.map((x,i)=>`<circle cx="${45+i*77}" cy="${150-x.value/max*110}" r="3.5" fill="white" stroke="#719251" stroke-width="2"/><text text-anchor="middle" x="${45+i*77}" y="179">${x.label}</text>`).join('')}</svg></div></section>`;}
function reports(){const m=metrics(state,reportFrom,reportTo);const best=state.products.map(p=>{const lines=m.sales.filter(s=>!s.refunded).flatMap(s=>s.items).filter(x=>x.productId===p.id);return {name:p.name,quantity:lines.reduce((a,x)=>a+x.quantity,0),revenue:lines.reduce((a,x)=>a+x.revenue,0)};}).filter(p=>p.quantity).sort((a,b)=>b.quantity-a.quantity);
 const periods=REPORT_PERIODS.map(p=>{const [from,to]=periodRange(p.id),on=from===reportFrom&&to===reportTo;return tile(p.label,p.tl,`${doAction('period')} data-period="${p.id}" aria-pressed="${on}"`,'calendar',on?'active':'');}).join('');
 return pageTitle('Reports','Ulat',button('Export sales','export-sales','secondary','down'))+`<section class="tile-grid three">${periods}</section><details class="custom-dates"><summary>Other dates · Ibang petsa</summary><div class="report-filters">${field('From','from','date',reportFrom,'id="report-from"')}${field('To','to','date',reportTo)}${button('Show','filter-reports')}</div></details><p class="period-line">${reportFrom===reportTo?date(reportFrom):`${date(reportFrom)} to ${date(reportTo)}`}</p><section class="big-numbers">${bigNumber('Sold','Benta',money(m.revenue),plural(m.sales.length,'sale'),'good')}${bigNumber('Profit','Kita',money(m.net),'After the cost of the rice and expenses',m.net<0?'warn':'')}${bigNumber('Expenses','Gastos',money(m.expenses),'Rent, transport, helpers and more')}</section>${weekChart()}<div class="two-col spacer"><section class="panel list-panel"><h2>Profit breakdown</h2>${rows([['Net sales',money(m.revenue)],['Cost of the rice sold',money(m.cost)],['Gross profit',money(m.profit)],['Expenses',money(m.expenses)],['Profit after expenses',money(m.net)],['Money received (cash, verified digital, utang payments)',money(m.collections)]])}<p class="subtitle">Rice lost or spoiled lowers the stock value; this pilot does not yet count it as an expense.</p></section><section class="panel"><div class="panel-head"><h2>Best-selling rice</h2></div>${table(['Rice','Kilos','Sold (before discounts)'],best.map(p=>row([e(p.name),qty(p.quantity)+' kg',money(p.revenue)])))}<div class="table-foot">Fully refunded sales are left out.</div></section></div><section class="panel spacer"><div class="panel-head"><h2>Sales in this period</h2></div>${salesTable([...m.sales].reverse())}</section>`;}

// ---------- Settings · Ayos ----------
// Receipt printer: paper size, Bluetooth and auto-print. Kept on this device (printer.js).
function printerPanel(){const settings=printerSettings(),name=printerName(),bluetooth=bluetoothAvailable();
 const papers=Object.entries(RECEIPT_PAPERS).map(([mm,p])=>{const on=Number(mm)===settings.paper;return tile(p.label,'',`${doAction('paper')} data-paper="${mm}" aria-pressed="${on}"`,'receipt',on?'active':'',`${p.hint} · ${p.columns} letters`);}).join('');
 const link=name?`<div class="notice green">Connected · ${e(name)}</div><div class="actions">${button('Disconnect','forget-printer','secondary','close')}</div>`:bluetooth?`<div class="actions">${button('Connect Bluetooth printer','connect-printer','','phone')}</div><p class="subtitle">Turn the printer on first. Chrome lists the nearby devices; pick your printer. Connect again after you reload the page.</p>`:'<div class="notice">This browser cannot use Bluetooth (for example on iPhone). The <b>Print</b> button still works with a USB printer or Save as PDF.</div>';
 return `<section class="panel list-panel printer-panel"><h2>Receipt printer <small lang="tl">· Printer ng resibo</small></h2><p class="subtitle">Paper size · Laki ng papel</p><div class="tile-grid two">${papers}</div>${link}${bluetooth?`<label class="checkbox"><input type="checkbox" ${doAction('auto-print')} ${settings.autoPrint?'checked':''}>Print the receipt by itself after each sale (Bluetooth)</label>`:''}<div class="actions spacer">${button('Test print','test-print','secondary','receipt')}</div><p class="subtitle">Printer settings stay on this device.</p></section>`;}
function settings(){return pageTitle('Settings','Ayos')+`<section class="tile-grid">${tile('Store name','Pangalan ng tindahan',doAction('profile'),'store')}${tile('Save a backup','I-save ang kopya',doAction('backup'),'down','good')}${tile('Restore a backup','Ibalik ang kopya',doAction('restore'),'clock')}${tile('Owner activity','Kasaysayan',doAction('audit'),'shield')}${tile('Start my own store','Bagong tindahan',doAction('setup'),'arrow')}</section><div class="two-col spacer">${printerPanel()}<section class="panel list-panel"><h2>Your store</h2>${rows([['Name',e(state.store.name)],['Owner',e(state.store.owner)],['Address',e(state.store.address||'Not set')],['Currency / Time zone','PHP / Asia–Manila']])}<p class="subtitle">Records are kept in this browser. Clearing browser data removes them, so save a backup often and before changing devices.</p></section></div><div class="notice spacer">This is a pilot for one device. It is not a cashier permission system and not a BIR-registered receipt or invoice system.</div>`;}

// ---------- Sales · Mga benta ----------
function history(){return pageTitle('Sales','Mga benta',button('New sale','pos','','plus'))+`<p class="period-line">Tap a sale number to see or print its receipt.</p><section class="panel">${salesTable([...state.sales].reverse())}</section>`;}

// ---------- Number pad for money and kilos (Utang, Cash, Stocks) ----------
const PAD_UNITS={peso:{decimals:2,show:v=>'₱'+v},kg:{decimals:PAD_MAX_DECIMALS,show:v=>v+' kg'}};
function keypad(){return `<div class="keypad">${[...'123456789','.','0'].map(k=>`<button type="button" data-key="${k}">${k}</button>`).join('')}<button type="button" data-key="back" aria-label="Erase">${icon('backspace')}</button></div>`;}
// Typing on a keypad: returns the new text, or null when the key is not allowed.
// The first key after a quick amount starts a new number; later keys add digits.
function padType(entry,fresh,key,decimals){if(key==='back')return fresh?'0':entry.slice(0,-1)||'0';if(key==='.'&&!fresh&&entry.includes('.'))return null;const next=fresh?(key==='.'?'0.':key):(entry==='0'&&key!=='.'?key:entry+key);return (next.split('.')[1]||'').length>decimals||next.length>PAD_MAX_LENGTH?null:next;}
// Screen keys and the computer keyboard (except while typing in a box).
function wireKeypad(form,press){form.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>press(b.dataset.key));form.onkeydown=ev=>{if(ev.target.matches('input:not([type="radio"]),select,textarea'))return;if(/^[0-9.]$/.test(ev.key))press(ev.key);else if(ev.key==='Backspace')press('back');else return;ev.preventDefault();};}
// start and quick values are typed text ("1000", "12.5"). warn(value) returns a message that blocks saving, or ''.
// onSubmit(value, formData): value is the typed text, so callers scale it like any form field.
function numberPad({title,intro='',unit='peso',start='0',quick=[],extra='',allowZero=false,warn=()=>'',submit='Save',onSubmit}){const u=PAD_UNITS[unit];let entry=start,fresh=true;
 modal(title,`${intro}<input type="hidden" name="amount"><output class="pad-display" aria-live="polite"><span class="pad-amount"></span><span class="pad-price"></span></output>${quick.length?`<div class="pad-quick">${quick.map(([v,l])=>`<button type="button" data-quick="${v}">${l}</button>`).join('')}</div>`:''}${keypad()}${extra}`,d=>onSubmit(d.amount,d),submit,'pad-dialog');
 const form=$('#modal-form'),save=form.querySelector('[type="submit"]');
 function refresh(){const value=entry.replace(/\.$/,'')||'0',message=warn(value);form.amount.value=value;form.querySelector('.pad-amount').textContent=u.show(entry);form.querySelector('.pad-price').textContent=message;form.querySelector('.pad-display').classList.toggle('warn',!!message);save.disabled=!!message||(!allowZero&&!(Number(value)>0));}
 const quickBox=form.querySelector('.pad-quick');if(quickBox)quickBox.onclick=ev=>{const b=ev.target.closest('[data-quick]');if(!b)return;entry=b.dataset.quick;fresh=true;refresh();};
 wireKeypad(form,key=>{const next=padType(entry,fresh,key,u.decimals);if(next===null)return;entry=next;fresh=false;refresh();});
 refresh();save.focus({preventScroll:true});}

// ---------- Cash box pop-ups ----------
const OPENING_QUICK=[500,1000,2000,3000];                // pesos of change money most stores start with
const COLLECT_QUICK=[100,500,1000];                      // pesos offered when collecting utang
const COLLECT_METHODS=PAY_METHODS.filter(m=>m.value==='Cash'||DIGITAL_METHODS.includes(m.value));
const DENOMINATIONS=[100000,50000,20000,10000,5000,2000,1000,500,100];   // centavos: ₱1,000 bill down to ₱1 coin
const EXPENSE_TYPES=[{value:'Transportation',icon:'truck',label:'Transport',tl:'Pamasahe, gasolina'},{value:'Rent',icon:'store',label:'Rent',tl:'Upa'},{value:'Electricity',icon:'bolt',label:'Electricity',tl:'Kuryente'},{value:'Labor',icon:'users',label:'Helpers',tl:'Sahod'},{value:'Packaging',icon:'box',label:'Plastic, sacks',tl:'Supot'},{value:'Maintenance',icon:'settings',label:'Repairs',tl:'Kumpuni'},{value:'Utilities',icon:'phone',label:'Water, phone',tl:'Tubig, load'},{value:'Miscellaneous',icon:'receipt',label:'Other',tl:'Iba pa'}];
// Closing: count the bills and coins; the app adds them up and shows short (kulang) or over (sobra).
function cashCount(){const expected=expectedCash(state);let typedTotal=false;
 modal('Count the money · Bilangin ang pera',`${bigNumber('Should be in the box','Dapat nasa kaha',money(expected))}<div class="counter">${DENOMINATIONS.map(v=>`<div class="count-row"><span class="denom">${bill(v)}</span><button type="button" class="step" data-count="${v}" data-step="-1" aria-label="One less ${bill(v)}">${icon('minus')}</button><input type="number" inputmode="numeric" min="0" step="1" value="0" name="n${v}" aria-label="How many ${bill(v)}"><button type="button" class="step" data-count="${v}" data-step="1" aria-label="One more ${bill(v)}">${icon('plus')}</button><strong class="count-sum">${bill(0)}</strong></div>`).join('')}</div><button type="button" class="text-link" id="type-total"></button><div id="typed-wrap" hidden>${num('Total counted ₱','typed','0')}</div><input type="hidden" name="actual"><div id="count-result" class="pay-result" aria-live="polite"></div><div class="field" id="reason-wrap" hidden><label for="f-reason">Why is it short or over? · Bakit kulang o sobra?</label><textarea id="f-reason" name="reason" rows="2"></textarea></div>`,async d=>{await commit('close',{actual:scaled(d.actual),reason:d.reason||''});toast('Cash box closed · Sarado na ang kaha.');},'Close the box · Isara','pad-dialog count-dialog');
 const form=$('#modal-form'),save=form.querySelector('[type="submit"]'),pieces=v=>Math.max(0,Math.floor(Number(form['n'+v].value))||0);
 const counted=()=>typedTotal?scaled(form.typed.value||'0'):DENOMINATIONS.reduce((a,v)=>a+v*pieces(v),0);
 function refresh(){const out=$('#count-result');$('#type-total').textContent=typedTotal?'Count bills and coins instead · Bilangin ang papel at barya':'Type the total instead · I-type ang kabuuan';$('#typed-wrap').hidden=!typedTotal;form.querySelector('.counter').hidden=typedTotal;
  try{const total=counted(),diff=total-expected;form.actual.value=(total/100).toFixed(2);form.querySelectorAll('.count-row').forEach((r,i)=>{r.querySelector('.count-sum').textContent=bill(DENOMINATIONS[i]*pieces(DENOMINATIONS[i]));});$('#reason-wrap').hidden=!diff;out.className='pay-result'+(diff?' warn':'');out.innerHTML=diff?`<span>${diff<0?'Short · Kulang':'Over · Sobra'}</span><strong>${money(Math.abs(diff))}</strong><small>You counted ${money(total)}</small>`:`<span>Correct · Tama</span><strong>${money(total)}</strong>`;save.disabled=false;}
  catch{out.className='pay-result warn';out.innerHTML='<span>Check the total you typed.</span>';save.disabled=true;}}
 form.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{const v=b.dataset.count;form['n'+v].value=Math.max(0,pieces(v)+Number(b.dataset.step));refresh();});
 $('#type-total').onclick=()=>{typedTotal=!typedTotal;refresh();};form.addEventListener('input',refresh);refresh();}
// ---------- Sell screen ----------
const unitGrams=(p,unit)=>unit==='sack'?p.sackGrams:1000;
const linePrice=(line,p)=>Math.round(line.quantity*(line.unit==='sack'?p.sackPrice:p.price)/unitGrams(p,line.unit));
const productOf=line=>state.products.find(p=>p.id===line.productId);
function cartTotal(){return cart.reduce((a,x)=>a+linePrice(x,productOf(x)),0);}
function amountText(line,p){if(line.unit!=='sack')return `${qty(line.quantity)} kg`;const sacks=line.quantity/p.sackGrams;return `${count(sacks)} sack${sacks===1?'':'s'} · ${qty(line.quantity)} kg`;}
function toneOf(p){return [...p.id].reduce((a,c)=>a+c.charCodeAt(0),0)%TILE_TONES;}
function productThumb(p,cls){const src=photoOf(photos,p.id);return `<span class="thumb ${cls} ${src?'has-photo':'tone-'+toneOf(p)}">${src?`<img src="${src}" alt="">`:icon('grain')}</span>`;}
function orderLine(line,i){const p=productOf(line),step=unitGrams(p,line.unit);return `<div class="order-line">${productThumb(p,'line-thumb')}<button class="line-info" data-action="edit-cart" data-index="${i}" aria-label="Change amount of ${e(p.name)}"><strong>${e(p.name)}</strong><small>${amountText(line,p)}</small></button><strong class="line-price">${money(linePrice(line,p))}</strong><div class="stepper"><button class="step" data-action="step-cart" data-index="${i}" data-step="-1" aria-label="One less" ${line.quantity<=step?'disabled':''}>${icon('minus')}</button><button class="step" data-action="step-cart" data-index="${i}" data-step="1" aria-label="One more">${icon('plus')}</button></div><button class="icon-btn remove" data-action="remove-cart" data-index="${i}" aria-label="Remove ${e(p.name)}">${icon('trash')}</button></div>`;}
function pos(){const categories=[ALL_PRODUCTS,...new Set(state.products.map(p=>p.category))],products=state.products.filter(p=>(category===ALL_PRODUCTS||p.category===category)&&(p.name+' '+p.sku).toLowerCase().includes(search.toLowerCase())),total=cartTotal(),items=`${cart.length} item${cart.length===1?'':'s'}`;
 const sessionNotice=currentSession(state)?'':`<div class="notice session-closed"><div><strong>Open the cash box first · Buksan ang kaha</strong><span>Count the change money in the drawer before the first sale.</span></div>${button('Open cash box','open','','arrow')}</div>`;
 const tiles=products.map(p=>{const line=cart.find(x=>x.productId===p.id),out=!p.stock,low=!out&&p.stock<=p.minimum;return `<button class="product-tile ${line?'in-cart':''}" data-action="add-to-cart" data-id="${p.id}" ${out?'disabled':''}>${productThumb(p,'tile-thumb')}<strong class="tile-name">${e(p.name)}</strong><span class="tile-price">${money(p.price)}<small> / kg</small></span><span class="tile-stock ${out||low?'warn':''}">${out?'Out of stock · Ubos na':`${qty(p.stock)} kg left${low?' · Low':''}`}</span>${line?`<span class="tile-badge">${icon('check')} ${amountText(line,p)}</span>`:''}</button>`;}).join('')||(state.products.length?'<div class="empty">No rice matches your search.</div>':`<div class="empty"><strong>No rice yet.</strong><br>Add your rice first, then come back to sell.<br><br>${button('Add rice in Stocks','inventory','','box')}</div>`);
 const lines=cart.length?cart.map(orderLine).join(''):`<div class="empty">${icon('cart')}<br><strong>Tap a rice to start.</strong><br><span lang="tl">Pindutin ang bigas para magsimula.</span></div>`;
 return `${sessionNotice}<div class="sell"><section class="shelf" aria-label="Products"><div class="shelf-top"><div class="search">${icon('search')}<input id="search" placeholder="Search rice · Hanapin" aria-label="Search products" value="${e(search)}"></div>${button('Sales today','history','secondary','receipt')}</div><div class="filters">${categories.map(c=>`<button class="filter ${c===category?'active':''}" data-category="${e(c)}">${e(c)}</button>`).join('')}</div><div class="product-grid">${tiles}</div></section><section class="order" id="checkout" aria-label="Current order"><div class="order-head"><h2>Order <small lang="tl">· Bilihin</small></h2><span>${items}</span></div><div class="order-lines">${lines}</div><div class="order-foot"><div class="order-total"><span>Total</span><strong>${money(total)}</strong></div><div class="order-actions">${held?button('Resume · Ibalik','resume','secondary','clock'):button('Hold · Itabi','hold','secondary','clock')}${button('Clear · Burahin','clear-cart','secondary','trash')}</div><button class="btn pay-btn" data-action="checkout" ${!cart.length||!currentSession(state)?'disabled':''}>${icon('cash')} Checkout · Bayad</button><p class="order-note">Internal sales record · Not a tax invoice</p></div></section></div>${cart.length?`<button class="btn mobile-checkout" data-action="go-checkout">${icon('cart')} ${items} · ${money(total)} · See order</button>`:''}`;}
// onSubmit may return a function; it runs after the dialog closes (e.g. to show the receipt).
// variant is a CSS class for larger dialogs such as the keypad and checkout.
function modal(title,body,onSubmit,submit='Save',variant=''){const dialog=$('#modal');document.body.append($('#toast'));dialog.className=variant;dialog.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="dismiss" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${onSubmit?'<form id="modal-form">':''}${body}<div class="error" id="modal-error" role="alert"></div><div class="modal-actions">${button(onSubmit?'Cancel':'Close','dismiss','secondary')}${onSubmit?`<button class="btn" type="submit">${submit}</button>`:''}</div>${onSubmit?'</form>':''}</div>`;dialog.showModal();dialog.querySelectorAll('[data-action="dismiss"]').forEach(b=>b.onclick=()=>dialog.close());bindActions(dialog);if(onSubmit)$('#modal-form').onsubmit=async ev=>{ev.preventDefault();if(busy)return;busy=true;const submit=ev.target.querySelector('[type="submit"]');submit.disabled=true;try{const after=await onSubmit(Object.fromEntries(new FormData(ev.target)),ev.target);dialog.close();render();if(typeof after==='function')after();}catch(err){$('#modal-error').textContent=err.message;}finally{busy=false;submit.disabled=false;}};}
const productOptions=()=>state.products.map(p=>[p.id,p.name]);
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const csvCell=x=>'"'+String(x??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';
function csv(name,headers,rows){download(name,'\uFEFF'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv');}
function backup(){download(`storepos-backup-${day()}.json`,JSON.stringify(state,null,2),'application/json');}
// ---------- Receipt: a store receipt that slides out of a printer ----------
const paperOf=()=>RECEIPT_PAPERS[printerSettings().paper]||RECEIPT_PAPERS[DEFAULT_PAPER];
const MM_PER_PX=25.4/96,PRINT_FONT_RATIO=.6,PRINT_TAIL_MM=10;   // Courier letters are 0.6 of their height wide; blank paper left to tear off
let receiptShown=[];                            // rows of the receipt on screen, for the Print button
function paperHtml(rows){return `<div class="receipt-paper" style="--cols:${paperOf().columns};--rows:${rows.length}">${rows.map(r=>`<div class="${r.style}">${e(r.text)||'&nbsp;'}</div>`).join('')}</div>`;}
function saleReceiptRows(s,tendered=0){const customer=state.customers.find(c=>c.id===s.customerId)?.name||'',payments=state.payments.filter(p=>p.saleId===s.id&&p.kind==='Sale');return receiptRows(receiptLines(s,{store:state.store,cashier:s.actor,customer,payments,tendered,debt:saleDebt(s)}),paperOf().columns);}
// A pretend sale for "Test print" in Settings; it is never saved.
const testSale=()=>({ref:'TEST PRINT',at:new Date().toISOString(),items:[{name:'Sample rice',quantity:2000,unit:'kg',unitGrams:1000,price:5800,revenue:11600}],subtotal:11600,discount:0,total:11600,refunded:false});
// tendered: cash the customer handed over, known only right after checkout (for the Sukli line).
function receipt(id,tendered=0,justSold=false){showReceipt(saleReceiptRows(state.sales.find(x=>x.id===id),tendered));if(justSold&&printerSettings().autoPrint&&printerName())printReceipt().catch(err=>toast(err.message));}
function showReceipt(rows){receiptShown=rows;
 modal('Receipt · Resibo',`<div class="printer" aria-hidden="true"><span class="printer-light"></span><span class="printer-slot"></span></div><div class="paper-window">${paperHtml(rows)}</div><div class="receipt-actions">${button('Print · I-print','print-receipt','','receipt')}${bluetoothAvailable()&&!printerName()?button('Connect printer','connect-printer','secondary','phone'):''}</div>`,null,'','receipt-dialog');}
async function printReceipt(){if(printerName()){toast(`Printing on ${printerName()}…`);await sendToPrinter(escPos(receiptShown));return;}printOnPaper(receiptShown);}
// Print backup (USB printers, PDF): only the receipt, on a page exactly as wide and as long as the paper.
function printOnPaper(rows){const paper=paperOf(),sheet=document.createElement('div'),page=document.createElement('style');
 sheet.id='print-receipt';sheet.innerHTML=paperHtml(rows);sheet.style.width=paper.printMm+'mm';sheet.style.fontSize=(paper.printMm/paper.columns/PRINT_FONT_RATIO)+'mm';document.body.append(sheet);
 const heightMm=Math.ceil(sheet.offsetHeight*MM_PER_PX)+PRINT_TAIL_MM;
 page.textContent=`@page{size:${paper.mm}mm ${heightMm}mm;margin:0}`;document.head.append(page);document.body.classList.add('printing-receipt');
 const cleanup=()=>{sheet.remove();page.remove();document.body.classList.remove('printing-receipt');};window.addEventListener('afterprint',cleanup,{once:true});window.print();}
