function validateBackup(s){if(s?.schema!==1||!s.store||typeof s.store.name!=='string'||typeof s.store.owner!=='string')throw Error('This is not a supported StorePOS backup.');for(const key of ['products','customers','sales','payments','ledger','movements','purchases','expenses','sessions','cashMoves','refunds','audit','processed'])if(!Array.isArray(s[key]))throw Error('Backup is missing '+key);const ids=new Set();for(const p of s.products){if(!p.id||ids.has(p.id)||!['name','sku','category'].every(k=>typeof p[k]==='string')||!['stock','stockValue','price','cost','minimum','sackPrice','sackGrams'].every(k=>Number.isSafeInteger(p[k])&&p[k]>=0)||!p.sackGrams)throw Error('Backup contains invalid product data.');ids.add(p.id);}for(const c of s.customers)if(typeof c.name!=='string'||!Number.isSafeInteger(c.limit)||c.limit<0)throw Error('Backup contains invalid customer data.');for(const key of ['payments','ledger','expenses','cashMoves'])for(const r of s[key])if(!Number.isSafeInteger(r.amount)||!Number.isFinite(Date.parse(r.at)))throw Error('Backup contains invalid financial records.');for(const sale of s.sales)if(!Array.isArray(sale.items)||!Number.isSafeInteger(sale.total)||!Number.isSafeInteger(sale.cost)||!Number.isFinite(Date.parse(sale.at))||sale.items.some(x=>!ids.has(x.productId)||!Number.isSafeInteger(x.quantity)||x.quantity<=0||!Number.isSafeInteger(x.cost)||!Number.isSafeInteger(x.revenue)))throw Error('Backup contains invalid sales records.');if(s.sessions.filter(x=>!x.closedAt).length>1)throw Error('Backup contains overlapping cash sessions.');}
// ---------- Weight keypad: "how much rice?" ----------
const padValue=n=>String(+n.toFixed(PAD_MAX_DECIMALS));
const padLabel=n=>n===.5?'½':padValue(n);
// Quick buy: when the order is empty, the same pop-up also takes the payment, so one rice is sold in one pop-up.
function weightPad(p,index){const existing=cart[index],quickBuy=!existing&&!cart.length&&!!currentSession(state);let unit=existing?.unit||'kg',entry=existing?padValue(existing.quantity/unitGrams(p,unit)):'1',fresh=true;
 const gramsNow=()=>Math.round(scaled(entry.replace(/\.$/,'')||'0',PAD_MAX_DECIMALS)*unitGrams(p,unit)/1000);
 const pad=`<div class="pad-product">${productThumb(p,'pad-thumb')}<div><strong>${money(p.price)} / kg</strong><small>${money(p.sackPrice)} per ${qty(p.sackGrams)} kg sack · ${qty(p.stock)} kg left</small></div></div><div class="unit-switch" role="group" aria-label="Sell by"><button type="button" data-unit="kg">By kilo · Kilo</button><button type="button" data-unit="sack">By sack · Sako</button></div><input type="hidden" name="unit"><input type="hidden" name="quantity"><output class="pad-display" aria-live="polite"><span class="pad-amount"></span><span class="pad-price"></span></output><div class="pad-quick"></div>${keypad()}`;
 modal(e(p.name),quickBuy?`<div class="quick-grid"><section>${pad}</section><section class="co-pay">${payPanel()}</section></div><input type="hidden" name="payNow" value="">`:pad,async d=>{const grams=Math.round(scaled(d.quantity,PAD_MAX_DECIMALS)*unitGrams(p,d.unit)/1000);if(!grams||grams>p.stock)throw Error(`Enter an amount up to ${qty(p.stock)} kg.`);const line={productId:p.id,quantity:grams,unit:d.unit};if(d.payNow)return afterSale(await saveSale(uid(),[line],d,linePrice(line,p)));const other=cart.findIndex((x,i)=>x.productId===p.id&&i!==index);if(other>=0)throw Error('This rice is already in the order. Change it there.');if(index>=0)cart[index]=line;else cart.push(line);},existing?'Update order':'Add to order',quickBuy?'pad-dialog quick-dialog':'pad-dialog');
 const dialog=$('#modal'),form=$('#modal-form'),submit=form.querySelector('[type="submit"]'),label=submit.textContent;
 // Quick buy: "Bayad na" comes first in the form, so pressing Enter after typing the cash also pays.
 let payButton=null,refreshPay=()=>{};
 if(quickBuy){submit.classList.add('secondary');submit.insertAdjacentHTML('beforebegin',`<button class="btn pay-now" type="submit"></button>`);payButton=form.querySelector('.pay-now');payButton.onclick=()=>{form.payNow.value='yes';};submit.onclick=()=>{form.payNow.value='';};refreshPay=wirePayPanel(form,()=>linePrice({quantity:gramsNow(),unit},p));}
 function refresh(){const value=entry.replace(/\.$/,'')||'0',grams=gramsNow(),over=grams>p.stock,price=grams?money(linePrice({quantity:grams,unit},p)):'';
  form.unit.value=unit;form.quantity.value=value;
  dialog.querySelectorAll('[data-unit]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.unit===unit)));
  dialog.querySelector('.pad-amount').textContent=unit==='sack'?`${entry} sack${value==='1'?'':'s'}`:`${entry} kg`;
  dialog.querySelector('.pad-price').textContent=over?`Only ${qty(p.stock)} kg left`:price&&`= ${price}`;
  dialog.querySelector('.pad-display').classList.toggle('warn',over);
  submit.disabled=!grams||over;submit.textContent=grams&&!over&&!quickBuy?`${label} · ${price}`:label;   // quick buy shows the price once, on "Bayad na"
  if(payButton){payButton.disabled=submit.disabled;payButton.innerHTML=`${icon('cash')} Bayad na${grams&&!over?' · '+price:''}`;refreshPay();}}
 function quick(){dialog.querySelector('.pad-quick').innerHTML=(unit==='sack'?SACK_QUICK.map(n=>[padValue(n),`${n} sack${n===1?'':'s'}`]):KILO_QUICK.map(g=>[padValue(g/1000),`${padLabel(g/1000)} kg`])).map(([v,l])=>`<button type="button" data-quick="${v}">${l}</button>`).join('');}
 wireKeypad(form,key=>{const next=padType(entry,fresh,key,PAD_MAX_DECIMALS);if(next===null)return;entry=next;fresh=false;refresh();});
 dialog.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{if(unit===b.dataset.unit)return;unit=b.dataset.unit;entry='1';fresh=true;quick();refresh();});
 dialog.querySelector('.pad-quick').onclick=ev=>{const b=ev.target.closest('[data-quick]');if(!b)return;entry=b.dataset.quick;fresh=true;refresh();};
 quick();refresh();submit.focus({preventScroll:true});}

// ---------- Checkout: "how will they pay?" ----------
// Same payment rules as before: cash above the total becomes change, anything unpaid becomes utang.
function paymentsFrom(d,total){if(d.method==='Utang')return [];if(d.method==='Split payment')return [{method:'Cash',amount:scaled(d.cash||'0')},{method:d.digitalMethod,amount:scaled(d.digital||'0'),verified:d.verified==='on',reference:d.reference}];const received=scaled(d.received||'0');return [{method:d.method,amount:d.method==='Cash'?Math.min(received,total):received,verified:d.verified==='on',reference:d.reference}];}
function tenderOf(d){return d.method==='Utang'?0:d.method==='Split payment'?scaled(d.cash||'0')+scaled(d.digital||'0'):scaled(d.received||'0');}
function cashSuggestions(total){return [total,...new Set(CASH_ROUND_UPS.map(step=>Math.ceil(total/step)*step).filter(v=>v>total))];}
function payFields(method,total){const amount=(total/100).toFixed(2),verify=check('I checked the money arrived · Pumasok na','verified');
 if(method==='Cash')return `<label>Customer gave · Bigay ng customer</label><div class="cash-quick">${cashSuggestions(total).map((v,i)=>`<button type="button" data-cash="${(v/100).toFixed(2)}">${i?money(v):'Exact · Sakto'}</button>`).join('')}</div>${num('Cash received ₱','received',amount)}`;
 if(method==='Utang')return '<div class="notice">The whole amount goes to the customer’s utang. Choose the customer above.</div>';
 if(method==='Split payment')return `<div class="fields">${num('Cash ₱','cash','0')}${num('E-wallet or bank ₱','digital',amount)}</div>${select('E-wallet or bank','digitalMethod',DIGITAL_METHODS)}${field('Reference no.','reference')}${verify}`;
 return `${num('Amount received ₱','received',amount)}${field('Reference no. (from their phone)','reference')}${verify}`;}
function checkoutPad(){if(!cart.length)return;const subtotal=cartTotal();
 const summary=cart.map(line=>{const p=productOf(line);return `<div class="sum-line">${productThumb(p,'line-thumb')}<span><strong>${e(p.name)}</strong><small>${amountText(line,p)}</small></span><strong>${money(linePrice(line,p))}</strong></div>`;}).join('');
 modal('Checkout · Bayad',`<div class="checkout-grid"><section class="co-summary"><h3>Order summary</h3>${summary}<div class="sum-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div>${num('Discount ₱ (optional)','discount','0')}<div class="sum-total"><span>Total</span><strong id="co-total">${money(subtotal)}</strong></div></section><section class="co-pay">${payPanel()}</section></div>`,async d=>{const sold=await saveSale(cartId,cart,d,subtotal);cart=[];cartId=uid();return afterSale(sold);},'Done · Tapos na','checkout-dialog');
 const form=$('#modal-form');wirePayPanel(form,()=>subtotal-scaled(form.discount.value||'0'),{totalFields:['discount'],onTotal:total=>{$('#co-total').textContent=money(total);}});form.querySelector('[type="submit"]').focus({preventScroll:true});}
async function saveSale(saleId,items,d,subtotal){const discount=scaled(d.discount||'0'),total=subtotal-discount;await commit('sale',{items,discount,payments:paymentsFrom(d,total),customerId:d.customerId,dueDate:d.dueDate},saleId);return {saleId,tendered:d.method==='Cash'?tenderOf(d):0};}
const afterSale=({saleId,tendered})=>()=>{toast('Sale saved. Stock and balances updated.');receipt(saleId,tendered,true);};
// Payment part of a sale pop-up (checkout and quick buy): method tiles, customer, amount boxes and the big Sukli box.
function payPanel(){return `<h3>How will they pay? <small lang="tl">· Paano magbabayad?</small></h3>${choiceTiles('method',PAY_METHODS,PAY_METHODS[0].value,'Payment method')}${select('Customer · Suki','customerId',[['','Walk-in · No name'],...state.customers.map(c=>[c.id,c.name])])}<div id="pay-fields"></div><div id="due-wrap" hidden>${field('Pay the rest by · Babayaran sa','dueDate','date',day())}</div><div id="pay-result" class="pay-result" aria-live="polite"></div>`;}
// totalOf() = amount due now (throws while a typed amount is invalid); totalFields = inputs that change it.
// Until the cashier types an amount, the amount received follows the total. Returns refresh() for total changes made by code.
function wirePayPanel(form,totalOf,{totalFields=[],onTotal=()=>{}}={}){const formData=()=>Object.fromEntries(new FormData(form));let typed=false;
 const totalNow=()=>{try{return Math.max(0,totalOf());}catch{return 0;}};
 function preview(){const d=formData(),out=$('#pay-result');try{const total=totalOf();if(total<0)throw Error();onTotal(total);const tender=tenderOf(d),unpaid=total-tender;$('#due-wrap').hidden=unpaid<=0;
   if(unpaid>0){out.className='pay-result warn';out.innerHTML=`<span>${d.method==='Utang'?'Utang · Listahan':'Unpaid · Kulang'}</span><strong>${money(unpaid)}</strong><small>${d.customerId?'Goes to this customer’s utang.':'Choose the customer above.'}</small>`;}
   else if(d.method==='Cash'){out.className='pay-result';out.innerHTML=`<span>Change · Sukli</span><strong>${money(tender-total)}</strong>`;}
   else if(tender>total){out.className='pay-result warn';out.innerHTML=`<span>More than the total</span><strong>${money(tender-total)}</strong><small>Check the amounts.</small>`;}
   else{out.className='pay-result';out.innerHTML=`<span>Fully paid · Bayad na</span><strong>${money(total)}</strong>`;}}
  catch{out.className='pay-result warn';out.innerHTML='<span>Check the amounts you typed.</span>';}}
 function showFields(){$('#pay-fields').innerHTML=payFields(formData().method,totalNow());typed=false;form.querySelectorAll('[data-cash]').forEach(b=>b.onclick=()=>{form.received.value=b.dataset.cash;typed=true;form.querySelectorAll('[data-cash]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));preview();});preview();}
 form.addEventListener('input',ev=>{const name=ev.target.name;if(name==='method'||(totalFields.includes(name)&&!typed))return showFields();if(TENDER_FIELDS.includes(name))typed=true;preview();});
 showFields();return ()=>typed?preview():showFields();}

// ---------- Product photo (owner, Stocks screen) ----------
function photoPad(p){const src=photoOf(photos,p.id);
 modal(`Photo · ${e(p.name)}`,`<div class="photo-pad">${productThumb(p,'photo-preview')}<p class="subtitle">Take or choose a clear picture of this rice or its sack. It shows on the Sell screen of this device.</p><label class="btn secondary photo-pick">${icon('camera')} ${src?'Change photo':'Choose photo'}<input type="file" accept="image/*" hidden></label>${src?`<button class="btn ghost" type="button" id="photo-remove">${icon('trash')} Remove photo</button>`:''}</div>`,null);
 const dialog=$('#modal'),picker=dialog.querySelector('input[type="file"]'),remove=$('#photo-remove');
 const done=message=>{dialog.close();render();toast(message);};
 picker.onchange=async()=>{try{await savePhoto(photos,p.id,await shrinkPhoto(picker.files[0]));done('Photo saved on this device.');}catch(err){$('#modal-error').textContent=err.message;}};
 if(remove)remove.onclick=async()=>{try{await removePhoto(photos,p.id);done('Photo removed.');}catch(err){$('#modal-error').textContent=err.message;}};}
// Menu buttons (data-page) and action buttons (data-action) work the same on screens and inside pop-ups.
function bindActions(root){root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if($('#modal').open)$('#modal').close();page=b.dataset.page;search='';render();window.scrollTo(0,0);});root.querySelectorAll('[data-action]:not([data-action="dismiss"])').forEach(b=>b.onclick=async()=>{try{await action(b.dataset.action,b);}catch(err){toast(err.message);}});}
function bind(){bindActions($('#app'));document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render();});const input=$('#search');if(input)input.oninput=()=>{const start=input.selectionStart;search=input.value;render();$('#search').focus();$('#search').setSelectionRange(start,start);};}
function render(){if(online&&cloudUser?.role==='cashier'&&![...CASHIER_PAGES,'history'].includes(page))page='pos';renderBase();if(online)decorateCloud();decorateMode();}
function decorateCloud(){const owner=cloudUser.role==='owner';const brand=$('.brand img');if(brand)brand.src=window.STOREPOS_ICON||'icon.svg';const saved=$('.saved');if(saved)saved.innerHTML='<span class="dot"></span> Shared store · Online';const picker=$('.store-picker small');if(picker)picker.textContent='Rice retail · Online store';const pilot=$('.pilot');if(pilot)pilot.innerHTML='<strong>StorePOS Online · Pilot</strong>Shared records across your devices.<br>Internet required for checkout.';const ownerBlock=$('.owner');if(ownerBlock)ownerBlock.innerHTML=`<span class="avatar">${e(cloudUser.name.slice(0,2).toUpperCase())}</span><div>${e(cloudUser.name)}<small>${owner?'Owner':'Cashier'} workspace</small></div>`;const actions=$('.top-actions');actions.insertAdjacentHTML('beforeend',`<button class="text-link" id="cloud-refresh">Refresh</button><button class="text-link" id="cloud-logout">Sign out</button>`);$('#cloud-refresh').onclick=()=>refreshCloud(true).catch(err=>toast(err.message));$('#cloud-logout').onclick=async()=>{if(pendingCommand()){toast('Confirm the pending save before signing out.');return;}if(cart.length||held){toast('Complete or clear your basket before signing out.');return;}try{await cloudCall('apiLogout',cloudToken());}catch{}cloudForget();state=null;cloudLoginScreen();};if(pendingCommand()){$('.workspace').insertAdjacentHTML('afterbegin','<div class="notice">A transaction needs confirmation. <button id="cloud-pending" class="text-link">Check pending save</button></div>');$('#cloud-pending').onclick=checkPendingCloud;}if(!owner){document.querySelectorAll('[data-page]').forEach(b=>{if(!CASHIER_PAGES.includes(b.dataset.page))b.remove();});document.querySelectorAll('[data-action]').forEach(b=>{if(['refund','customer','expense','cash-move'].includes(b.dataset.action))b.remove();});}if(page==='settings'&&owner){const workspace=$('.workspace');workspace.innerHTML=head('Your online store','One shared store, wherever you log in.')+`<div class="notice green">Records are saved to your private Google Sheet through Apps Script. Each staff member uses their own access account. Keep the database Sheet private.</div><div class="two-col"><section class="panel list-panel"><h2>Store profile</h2><div class="row"><span>Store name</span><strong>${e(state.store.name)}</strong></div><div class="row"><span>Business address</span><strong>${e(state.store.address||'Not set')}</strong></div><div class="spacer">${button('Edit store profile','profile','secondary')}</div></section><section class="panel list-panel"><h2>People & access</h2><p class="subtitle">Owners manage stock, costs, reports, and returns. Cashiers can sell, collect utang, and close their own register session.</p><div class="spacer"><button class="btn secondary" id="manage-staff">Manage staff</button></div></section><section class="panel list-panel"><h2>Backup & activity</h2><p class="subtitle">Download regular backups. Restore and store migration are controlled administrator operations.</p><div class="actions spacer">${button('Download backup','backup','secondary','down')}${button('Audit trail','audit','secondary','clock')}</div></section><section class="panel list-panel"><h2>Online pilot scope</h2><p class="subtitle">One shared cash register. The owner can monitor from another device. Simultaneous edits are checked before saving; outdated transactions must be reviewed. No offline transaction queue or registered tax invoicing yet.</p></section>${printerPanel()}</div>`;bind();$('#manage-staff').onclick=()=>manageStaffCloud().catch(err=>toast(err.message));}}
function cloudLoginScreen(message=''){if($('#modal').open)$('#modal').close();$('#app').innerHTML=`<main class="login-page"><section class="login-card"><div class="brand"><img src="${window.STOREPOS_ICON||'icon.svg'}" alt=""><div><strong>StorePOS<span>YOUR STORE, WHEREVER YOU ARE.</span></strong></div></div><h1>Welcome to your store.</h1><p class="subtitle">Sign in to see the same sales, stocks, and utang on every device.</p><form id="cloud-login" class="spacer">${field('Username','username','text','','required autocomplete="username"')}${field('Access code','code','password','','required autocomplete="current-password"')}<p class="subtitle">Use the access code provided by your store owner.</p><div class="error spacer" id="login-error">${e(message)}</div><button class="btn full" type="submit">Sign in</button></form><button class="btn secondary full spacer" id="google-owner">Google owner sign-in</button><p class="subtitle" style="text-align:center">Online store · Internet connection required</p></section></main>`;$('#cloud-login').onsubmit=async ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));ev.target.querySelector('button').disabled=true;try{const result=await cloudCall('apiSignIn',d.username,d.code.trim());cloudAccept(result);state=result.state;page=cloudUser.role==='owner'?'dashboard':'pos';render();}catch(err){$('#login-error').textContent=err.message;ev.target.querySelector('button').disabled=false;}};$('#google-owner').onclick=async()=>{try{const result=await cloudCall('apiOwnerSession');cloudAccept(result);state=result.state;page='dashboard';render();}catch(err){$('#login-error').textContent=err.message;}};}
async function startCloud(){if(cloudToken()){const result=await cloudCall('apiRead',cloudToken());setCloudUser(result.user);state=result.state;render();}else cloudLoginScreen();setInterval(()=>{if(!document.hidden&&state&&!busy&&!cart.length&&!held&&!$('#modal').open&&!pendingCommand()&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))refreshCloud(false).catch(()=>{});},60000);}
async function refreshCloud(explicit=false){if(busy)return;const result=await cloudCall('apiRead',cloudToken());const changed=result.state.revision!==state.revision;setCloudUser(result.user);state=result.state;if(changed){if($('#modal').open||cart.length){toast('Updated store records loaded. Review your current entry before saving.');}else render();}if(explicit)toast('Latest store records loaded.');}
async function checkPendingCloud(){const pending=pendingCommand();if(!pending||busy)return;busy=true;try{const result=await cloudCommand(pending.type,pending.data,pending.id,pending.expectedRevision);setCloudUser(result.user);state=result.state;if(result.conflict){render();toast('The store changed before this entry was saved. Review and enter it again.');return;}if(pending.type==='sale'){cart=[];cartId=uid();}render();toast('Confirmed: the transaction was saved once.');}catch(err){toast(err.message);if(!pendingCommand())render();}finally{busy=false;}}
async function manageStaffCloud(){const users=await cloudCall('apiListUsers',cloudToken());modal('Store access',table(['Name','Role','Status',''],users.map(u=>row([`${e(u.name)}<small>${e(u.username)}</small>`,e(u.role),u.active?'Active':'Disabled',u.active&&u.id!=='owner'&&u.id!==cloudUser.id?`<button class="text-link" data-disable-user="${e(u.id)}">Disable</button>`:'—'])))+'<div class="spacer"><button id="add-staff" class="btn">Add staff account</button></div>');$('#add-staff').onclick=()=>{$('#modal').close();modal('Add staff access',field('Name','name','text','','required')+field('Username','username','text','','required pattern="[a-zA-Z0-9._-]{3,40}"')+select('Role','role',[['cashier','Cashier'],['owner','Owner']]),async d=>{const result=await cloudCall('apiCreateUser',cloudToken(),d);setTimeout(()=>{modal('Save this access code',`<div class="notice">Share this code directly with ${e(result.user.name)}. It is shown only once. Anyone with the code can use this account.</div>${field('Username','staff-name','text',result.user.username,'readonly')}${field('Access code','access-code','text',result.code,'readonly')}<p class="subtitle">Store it securely. Disable this account if the code is lost or exposed.</p>`);},0);},'Create account');};$('#modal').querySelectorAll('[data-disable-user]').forEach(b=>b.onclick=()=>{const id=b.dataset.disableUser;$('#modal').close();modal('Disable staff access','<p class="subtitle">This immediately revokes the selected account’s sessions. Their transaction records remain.</p>',async()=>{await cloudCall('apiDisableUser',cloudToken(),id);toast('Staff access disabled.');},'Disable access');});}

photos=await openPhotos();
$('#modal').addEventListener('close',()=>document.body.append($('#toast')));
try{if(online){await startCloud();}else{db=await openDB();state=await read(db);if(!state){state=window.STOREPOS_PREVIEW?demoState():emptyState();await save(db,state,-1);}render();if(!window.STOREPOS_PREVIEW&&!window.STOREPOS_STANDALONE&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}}catch(err){if(online)cloudLoginScreen(err.message);else $('#app').innerHTML=`<div class="loading"><h1>We couldn’t open your store.</h1><p class="subtitle">${e(err.message)}</p><p class="subtitle">Allow browser storage, then reload. Existing records have not been reset.</p></div>`;}
window.addEventListener('beforeunload',ev=>{if(cart.length||held){ev.preventDefault();ev.returnValue='';}});

function decorateMode(){
 const brand=$('.brand img');if(brand&&window.STOREPOS_ICON)brand.src=window.STOREPOS_ICON;
 const preview=!!window.STOREPOS_PREVIEW;
 const mode=preview?'Preview · Sample data':online?'Online · Shared store':'Local · This device';
 const bar=document.createElement('div');bar.className='mode-banner';bar.innerHTML='<strong>'+mode+'</strong><span>'+(preview?'Try every workflow. Reload to reset; nothing is saved.':online?'Internet required. Separate from your local store.':'Saved in this browser. Back up regularly; no online sync.')+'</span>';
 $('.workspace').prepend(bar);
 if(preview){$('.saved').textContent='Preview · Not saved';document.querySelectorAll('[data-action="setup"],[data-action="restore"]').forEach(x=>x.remove());}
 document.querySelectorAll('input[type="number"]').forEach(x=>x.inputMode='decimal');
 const menu=$('.mobile-menu');if(menu)menu.setAttribute('aria-expanded','false');
}
